import dgeequb = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb( 'row-major', 2, 2, A, 2, R, C, out ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb( 5, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( true, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( false, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( null, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( undefined, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( [], 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( {}, 2, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( ( x: number ): number => x, 2, 2, A, 2, R, C, out ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb( 'row-major', '5', 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', true, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', false, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', null, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', undefined, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', [], 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', {}, 2, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', ( x: number ): number => x, 2, A, 2, R, C, out ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb( 'row-major', 2, '5', A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, true, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, false, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, null, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, undefined, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, [], A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, {}, A, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, ( x: number ): number => x, A, 2, R, C, out ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a Float64Array...
{
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb( 'row-major', 2, 2, '5', 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, 5, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, true, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, false, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, null, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, undefined, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, [], 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, {}, 2, R, C, out ); // $ExpectError
	dgeequb( 'row-major', 2, 2, ( x: number ): number => x, 2, R, C, out ); // $ExpectError
}

