// The compiler throws an error if the function is provided an eighth argument which is not a Float64Array...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );

	dgeequb( 'row-major', 2, 2, A, 2, R, C, '5' ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, 5 ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, true ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, false ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, null ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, undefined ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, [] ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, {} ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb(); // $ExpectError
	dgeequb( 'row-major' ); // $ExpectError
	dgeequb( 'row-major', 2 ); // $ExpectError
	dgeequb( 'row-major', 2, 2 ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2 ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C ); // $ExpectError
	dgeequb( 'row-major', 2, 2, A, 2, R, C, out, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb.ndarray( '5', 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( true, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( false, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( null, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( undefined, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( [], 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( {}, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( ( x: number ): number => x, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a Float64Array...
{
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb.ndarray( 2, 2, '5', 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, 5, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, true, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, false, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, null, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, undefined, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, [], 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, {}, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Float64Array( 4 );
	const R = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const out = new Float64Array( 3 );

	dgeequb.ndarray(); // $ExpectError
	dgeequb.ndarray( 2 ); // $ExpectError
	dgeequb.ndarray( 2, 2 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1 ); // $ExpectError
	dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0, 10 ); // $ExpectError
}
